map "https://fhir.labs.smartregister.org/fhir/StructureMap/261a2bd6-b9a1-11ed-afa1-0242ac120002" = "Pregnancy Visit"

uses "http://hl7.org/fhir/StructureDefinition/QuestionnaireReponse" as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" as target

group pregnancyVisit(source src : QuestionnaireResponse, target bundle: Bundle) {
    src -> bundle.type = "collection" "r_bundle_type";
    src -> evaluate(src, $this.subject) as refPatient then extractEncounter(src, bundle, refPatient) "r_bundle_entries";
}

group extractEncounter(source src : QuestionnaireResponse, target bundle : Bundle, source refPatient : Reference) {
    src -> bundle.entry as entry, entry.resource = create('Encounter') as encounter then {
        src -> encounter.id = uuid() "r_en_id";
        src -> encounter.status = 'finished' "r_en_st";
        src -> encounter.class = c("http://terminology.hl7.org/CodeSystem/v3-ActCode", "HH", "home health") "r_en_cls";
        src -> encounter.type = create('CodeableConcept') as concept then {
            src -> concept.coding = c("https://smartregister.org/", "pregnancy_visit") as coding then {
                src -> coding.display = 'Pregnancy visit' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Pregnancy visit' "r_en_typ_text";
        } "r_en_typ";
        src -> encounter.priority = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://terminology.hl7.org/ValueSet/v3-ActPriority", "EL") as coding then {
                src -> coding.display = 'Elective' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Elective' "r_en_prio_text";
        } "r_en_prio";
        src.subject as subject -> encounter.subject = subject "r_en_sub";

        src -> encounter.period = create('Period') as enPeriod then {
            src -> enPeriod.start = evaluate(src, now()) "r_en_per_start";
            src -> enPeriod.end = evaluate(src, now()) "r_en_per_end";
        } "r_en_per";
        src -> encounter.reasonCode = create('CodeableConcept') as concept then {
            src -> concept.coding = c("https://smartregister.org/", "pregnancy_visit") as coding then {
                src -> coding.display = 'Pregnancy visit' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Pregnancy visit' "r_en_text";
        } "r_en_reason";

         // Update the linked task with the output
         src.item as item where(linkId = "task-id") then {
             src -> bundle.entry as entry, entry.resource = create("Task") as task then {
               src -> task.id = create("id") as taskId then {
                    src -> taskId.value = evaluate(item, $this.answer.value) "r_item_task_id_value";
               } "r_task_id_val";
               src -> task.output = create('Task_Output') as outputTask then {
                    src -> outputTask.type = create("CodeableConcept") as concept then {
                          src-> concept.coding = c("http:snomed.info/sct","371531000") as coding then {
                              src -> coding.display = "Report of clinical encounter (record artifact)" "r_task_output_coding_display";
                          } "r_task_output_concept_coding";
                    } "r_task_output_codeable_concept";
                    src -> outputTask.value = reference(encounter) "r_task_output_reference";
               } "r_task_output_val";
             } "r_task_output";
         } "r_task_id_output";
    } "r_en";
}
